
export type FlagSpec = Record<string, { takesValue: boolean }>;

export type ParsedFlags = {
  values: Record<string, string | boolean>;
  positionals: string[];
  errors: string[];
};

export const parseFlags = (args: string[], spec: FlagSpec): ParsedFlags => {
  const values: Record<string, string | boolean> = {};
  const positionals: string[] = [];
  const errors: string[] = [];

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (!arg.startsWith('--')) {
      positionals.push(arg);
      continue;
    }

    const equalsIndex = arg.indexOf('=');
    const name = equalsIndex === -1 ? arg.slice(2) : arg.slice(2, equalsIndex);
    const inlineValue =
      equalsIndex === -1 ? undefined : arg.slice(equalsIndex + 1);
    const definition = spec[name];

    if (!definition) {
      errors.push(`Unknown flag --${name}`);
      continue;
    }

    if (!definition.takesValue) {
      if (inlineValue !== undefined) {
        errors.push(`Flag --${name} does not take a value`);
        continue;
      }
      values[name] = true;
      continue;
    }

    if (inlineValue !== undefined) {
      values[name] = inlineValue;
      continue;
    }

    const next = args[i + 1];
    if (next === undefined || next.startsWith('--')) {
      errors.push(`Flag --${name} requires a value`);
      continue;
    }
    values[name] = next;
    i++;
  }

  return { values, positionals, errors };
};

export const stringFlag = (
  parsed: ParsedFlags,
  name: string,
): string | undefined => {
  const value = parsed.values[name];
  return typeof value === 'string' ? value : undefined;
};

export const booleanFlag = (parsed: ParsedFlags, name: string): boolean =>
  parsed.values[name] === true;

export const integerFlag = (
  parsed: ParsedFlags,
  name: string,
): number | undefined => {
  const raw = stringFlag(parsed, name);
  if (raw === undefined) {
    return undefined;
  }
  const value = Number.parseInt(raw, 10);
  if (!Number.isInteger(value) || value <= 0) {
    parsed.errors.push(`Flag --${name} must be a positive integer`);
    return undefined;
  }
  return value;
};
